using System.Text.Json;using Servicio.RetazoMarket.Business.DTOs.Personalizacion;
namespace Servicio.RetazoMarket.Business.Validators;
public static class PersonalizacionValidator {private static readonly HashSet<string> Tipos=["LISTA","MATERIAL","TEXTO","MEDIDA","COLOR"];public static IReadOnlyCollection<string> Validar(CrearPersonalizacionRequest r)=>r is null?["La solicitud no puede ser nula."]:Campos(r.id_producto,r.nombre_atr,r.tipo_valor,r.valores_json,r.costo_adicional);public static IReadOnlyCollection<string> Validar(ActualizarPersonalizacionRequest r){if(r is null)return ["La solicitud no puede ser nula."];var e=Campos(r.id_producto,r.nombre_atr,r.tipo_valor,r.valores_json,r.costo_adicional).ToList();if(r.id_opcion<=0)e.Insert(0,"El id de la personalización es inválido.");return e;}public static IReadOnlyCollection<int> ObtenerMateriales(JsonElement json)=>json.TryGetProperty("opciones",out var opciones)&&opciones.ValueKind==JsonValueKind.Array?opciones.EnumerateArray().Where(x=>x.TryGetProperty("id_material",out _)).Select(x=>x.GetProperty("id_material").GetInt32()).ToList():[];private static IReadOnlyCollection<string> Campos(int producto,string? nombre,string? tipo,JsonElement json,decimal costo){var e=new List<string>();if(producto<=0)e.Add("El producto es obligatorio.");if(string.IsNullOrWhiteSpace(nombre)||nombre.Trim().Length>100)e.Add("El nombre del atributo es obligatorio y admite hasta 100 caracteres.");var t=tipo?.Trim().ToUpperInvariant();if(t is null||!Tipos.Contains(t))e.Add("El tipo debe ser LISTA, MATERIAL, TEXTO, MEDIDA o COLOR.");if(costo<0)e.Add("El costo adicional no puede ser negativo.");if(decimal.Round(costo,2)!=costo)e.Add("El costo adicional admite máximo dos decimales.");if(json.ValueKind!=JsonValueKind.Object){e.Add("valores_json debe ser un objeto.");return e;}if(!json.TryGetProperty("version",out var version)||version.ValueKind!=JsonValueKind.Number||!version.TryGetInt32(out var v)||v!=1)e.Add("valores_json.version debe ser 1.");if(!json.TryGetProperty("requerido",out var requerido)||(requerido.ValueKind is not(JsonValueKind.True or JsonValueKind.False)))e.Add("valores_json.requerido debe ser booleano.");if(t is "LISTA" or "COLOR")ValidarOpcionesTexto(json,e);else if(t=="MATERIAL")ValidarOpcionesMaterial(json,e);else if(t=="TEXTO")ValidarTexto(json,e);else if(t=="MEDIDA")ValidarMedida(json,e);return e;}private static void ValidarOpcionesTexto(JsonElement j,List<string> e){if(!j.TryGetProperty("opciones",out var o)||o.ValueKind!=JsonValueKind.Array||o.GetArrayLength()==0){e.Add("Las opciones deben contener al menos un elemento.");return;}var codigos=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var x in o.EnumerateArray()){if(x.ValueKind!=JsonValueKind.Object||!x.TryGetProperty("codigo",out var c)||c.ValueKind!=JsonValueKind.String||string.IsNullOrWhiteSpace(c.GetString())||!x.TryGetProperty("nombre",out var n)||n.ValueKind!=JsonValueKind.String||string.IsNullOrWhiteSpace(n.GetString()))e.Add("Cada opción requiere código y nombre.");else if(!codigos.Add(c.GetString()!.Trim()))e.Add("Los códigos de opciones no pueden repetirse.");ValidarCostoOpcion(x,e);}}private static void ValidarOpcionesMaterial(JsonElement j,List<string> e){if(!j.TryGetProperty("opciones",out var o)||o.ValueKind!=JsonValueKind.Array||o.GetArrayLength()==0){e.Add("Las opciones de material deben contener al menos un elemento.");return;}var ids=new HashSet<int>();foreach(var x in o.EnumerateArray()){if(x.ValueKind!=JsonValueKind.Object||!x.TryGetProperty("id_material",out var id)||!id.TryGetInt32(out var valor)||valor<=0)e.Add("Cada opción MATERIAL requiere un id_material positivo.");else if(!ids.Add(valor))e.Add("Los materiales permitidos no pueden repetirse.");ValidarCostoOpcion(x,e);}}private static void ValidarTexto(JsonElement j,List<string> e){if(!Entero(j,"longitud_minima",out var min)||!Entero(j,"longitud_maxima",out var max)||min<0||max<=0||min>max)e.Add("TEXTO requiere longitudes mínima y máxima válidas.");if(j.TryGetProperty("patron",out var p)&&p.ValueKind!=JsonValueKind.String)e.Add("El patrón de TEXTO debe ser una cadena.");}private static void ValidarMedida(JsonElement j,List<string> e){if(!Numero(j,"minimo",out var min)||!Numero(j,"maximo",out var max)||min>max)e.Add("MEDIDA requiere un rango válido.");if(!j.TryGetProperty("unidad",out var u)||u.ValueKind!=JsonValueKind.String||string.IsNullOrWhiteSpace(u.GetString())||u.GetString()!.Length>50)e.Add("MEDIDA requiere una unidad válida.");}private static void ValidarCostoOpcion(JsonElement x,List<string> e){if(x.TryGetProperty("costo_adicional",out var c)&&(!c.TryGetDecimal(out var valor)||valor<0))e.Add("El costo adicional de una opción no puede ser negativo.");}private static bool Entero(JsonElement j,string n,out int v){v=0;return j.TryGetProperty(n,out var x)&&x.TryGetInt32(out v);}private static bool Numero(JsonElement j,string n,out decimal v){v=0;return j.TryGetProperty(n,out var x)&&x.TryGetDecimal(out v);}}
